import type { AccordionIndicatorProps } from "../accordion.types";

import React from "react";
import { clsx } from "clsx";
import { ChevronDown, ChevronRight } from "@exp-textura/icons";

import { useAccordionSection } from "../hooks/use-accordion-section";
import { AccordionClasses } from "../accordion.styles";

const DEFAULT_LEADING_ICON = <ChevronRight />;
const DEFAULT_TRAILING_ICON = <ChevronDown />;

export const AccordionIndicator: React.FC<AccordionIndicatorProps> = ({
  icon,
  collapseIcon,
  className,
  isLeading = false,
  ...props
}) => {
  const { isExpanded } = useAccordionSection();

  const DefaultIcon = isLeading ? DEFAULT_LEADING_ICON : DEFAULT_TRAILING_ICON;

  const collapsedIconToShow = icon === undefined ? DefaultIcon : icon;
  const expandedIconToShow = collapseIcon === undefined ? collapsedIconToShow : collapseIcon;
  const applyRotation = collapseIcon === undefined;
  const iconToRender: React.ReactNode | null = isExpanded
    ? expandedIconToShow
    : collapsedIconToShow;

  return (
    <span
      className={clsx(AccordionClasses.indicator, className)}
      data-expanded={isExpanded && applyRotation}
      data-leading={isLeading}
      {...props}
    >
      {iconToRender}
    </span>
  );
};

AccordionIndicator.displayName = "Accordion.Indicator";
